/* Portfolio front end. Reads window.PORTFOLIO (data/manifest.js, generated by
   tools/build.py) and window.SITE (js/config.js). No build step, no framework. */
(function () {
  "use strict";
  const SITE = window.SITE || {};
  const DATA = window.PORTFOLIO || { home: [], series: [] };
  const series = (DATA.series || []).filter(s => !s.hidden);
  const $ = (sel, root) => (root || document).querySelector(sel);
  const el = (tag, attrs, children) => {
    const n = document.createElement(tag);
    for (const k in attrs || {}) {
      if (k === "class") n.className = attrs[k];
      else if (k === "html") n.innerHTML = attrs[k];
      else if (k === "text") n.textContent = attrs[k];
      else if (attrs[k] != null && attrs[k] !== false) n.setAttribute(k, attrs[k] === true ? "" : attrs[k]);
    }
    for (const c of children || []) if (c) n.append(c);
    return n;
  };
  const SINGLE = !!SITE.singlePage;
  const seriesHref = s => SINGLE ? `#series/${encodeURIComponent(s.slug)}` : `series.html?s=${encodeURIComponent(s.slug)}`;
  const infoHref = SINGLE ? "#info" : "info.html";
  const archiveHref = SINGLE ? "#archive" : "archive.html";
  const homeHref = SINGLE ? "#" : "index.html";
  const projectsHref = SINGLE ? "#projects" : "index.html#projects";
  const route = () => {
    const m = location.hash.match(/^#series\/([^/]+)/);
    if (m) return { series: decodeURIComponent(m[1]) };
    if (location.hash === "#info") return { info: true };
    if (location.hash === "#archive") return { archive: true };
    return {};
  };
  const linkTarget = SITE.openSeriesInNewTab ? "_blank" : null;

  /* srcset string from the manifest's {width: path} map */
  function srcsetOf(item) {
    return Object.keys(item.srcset || {}).sort((a, b) => a - b).map(w => `${item.srcset[w]} ${w}w`).join(", ");
  }

  /* <img> with responsive sources, aspect-ratio reserved, blurred placeholder */
  function picture(item, opts) {
    opts = opts || {};
    const img = el("img", {
      src: item.src, srcset: srcsetOf(item), sizes: opts.sizes || "100vw",
      width: item.width, height: item.height, alt: item.alt || "",
      loading: opts.eager ? "eager" : "lazy", decoding: "async",
      fetchpriority: opts.eager ? "high" : null,
      class: opts.eager ? "" : "lazy",
    });
    if (item.lqip) img.style.backgroundImage = `url("${item.lqip}")`;
    const done = () => { img.classList.add("is-loaded"); img.style.backgroundImage = ""; };
    if (img.complete && img.naturalWidth) done(); else img.addEventListener("load", done, { once: true });
    return img;
  }

  function video(item) {
    const v = el("video", {
      controls: true, playsinline: true, preload: "metadata", poster: item.poster || null,
      width: item.width || null, height: item.height || null,
      "aria-label": item.alt || "Video",
    });
    v.append(el("source", { src: item.src, type: mime(item.src) }));
    return v;
  }
  function mime(src) {
    const ext = src.split(".").pop().toLowerCase();
    return { mp4: "video/mp4", m4v: "video/mp4", webm: "video/webm", mov: "video/quicktime" }[ext] || "";
  }

  /* Header / footer shared by every page --------------------------------- */
  function header(current) {
    const h = $(".site-header");
    if (!h) return;
    const nav = [[projectsHref, "Projects"], [archiveHref, "Archive"], [infoHref, "Information"], [`mailto:${SITE.email || ""}`, "Contact"]];
    const r = route();
    const activeHref = SINGLE ? (r.info ? infoHref : r.archive ? archiveHref : projectsHref)
                              : (current === "info.html" ? infoHref : current === "archive.html" ? archiveHref : projectsHref);
    h.append(
      el("a", { class: "brand", href: homeHref }, [document.createTextNode(SITE.name || "Portfolio"),
        SITE.tagline ? el("small", { text: SITE.tagline }) : null]),
      el("nav", { class: "nav", "aria-label": "Site" }, nav.map(([href, label]) =>
        el("a", { href, text: label, "aria-current": href === activeHref ? "page" : null })))
    );
    document.title = current === "index.html" ? (SITE.name || "Portfolio") : document.title;
  }
  function footer() {
    const f = $(".site-footer");
    if (!f) return;
    f.append(el("span", { text: `© ${new Date().getFullYear()} ${SITE.name || ""}` }));
    if (SITE.instagram) f.append(el("a", { href: SITE.instagram, text: "Instagram", target: "_blank", rel: "noopener" }));
  }

  /* Home ------------------------------------------------------------------ */
  function home() {
    const root = $("#cycler");
    if (!root) return;
    if (SINGLE && (route().series || route().info || route().archive)) { root.hidden = true; $("#work").hidden = true; return; }
    root.hidden = false; $("#work").hidden = false;
    let frames = (DATA.home || []).slice();
    if (SITE.shuffleHome) for (let i = frames.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [frames[i], frames[j]] = [frames[j], frames[i]]; }
    if (!frames.length) {
      root.classList.add("is-empty");
      root.append(el("p", { class: "empty", text: "No photos yet. Add images to originals/ and run tools/build.py." }));
      return;
    }
    const nodes = frames.map((f, i) => {
      const img = picture(f, { eager: i < 2, sizes: "100vw" });
      img.draggable = false;
      return el("div", { class: "frame" + (i === 0 ? " is-on" : ""), "data-i": i }, [img]);
    });
    const caption = el("div", { class: "caption" }, [
      el("span", { class: "title" }), el("span", { class: "hint", text: "Paused — click to continue, double-click to open" })]);
    root.append(...nodes, caption);

    let i = 0, timer = null, paused = false;
    const loaded = new Set();
    nodes.forEach((n, k) => { const img = n.firstChild; const mark = () => loaded.add(k); if (img.complete && img.naturalWidth) mark(); else img.addEventListener("load", mark); });

    function show(k) {
      nodes[i].classList.remove("is-on"); i = k; nodes[i].classList.add("is-on");
      const f = frames[i], s = series.find(x => x.slug === f.series);
      caption.firstChild.textContent = s ? `${s.title}${s.year ? ", " + s.year : ""}` : "";
      root.dataset.series = f.series || "";
      // warm the next couple of frames
      for (let d = 1; d <= 2; d++) { const n = nodes[(i + d) % nodes.length].firstChild; if (n.loading === "lazy") n.loading = "eager"; }
    }
    function next() {
      // skip frames that haven't arrived yet, so the rhythm never shows a blank
      for (let d = 1; d <= nodes.length; d++) { const k = (i + d) % nodes.length; if (loaded.has(k) || d === nodes.length) { show(k); break; } }
    }
    function start() { stop(); timer = setInterval(next, Math.max(80, SITE.cycleMs || 400)); root.classList.remove("is-paused"); paused = false; }
    function stop() { if (timer) clearInterval(timer); timer = null; }
    function pause() { stop(); root.classList.add("is-paused"); paused = true; }
    show(0); start();

    if (SITE.pauseOnHover && matchMedia("(hover: hover)").matches) {
      root.addEventListener("mouseenter", pause); root.addEventListener("mouseleave", start);
    }
    document.addEventListener("visibilitychange", () => document.hidden ? stop() : (!paused && start()));

    // Click (or tap) pauses/resumes; double-click or Enter opens the series the frame belongs to.
    let clickTimer = null;
    root.addEventListener("click", () => {
      if (clickTimer) { clearTimeout(clickTimer); clickTimer = null; open(); return; }
      clickTimer = setTimeout(() => { clickTimer = null; paused ? start() : pause(); }, 260);
    });
    root.tabIndex = 0; root.setAttribute("role", "button"); root.setAttribute("aria-label", "Home gallery. Click to pause, double-click to open the series.");
    root.addEventListener("keydown", e => {
      if (e.key === " ") { e.preventDefault(); paused ? start() : pause(); }
      if (e.key === "Enter") open();
      if (e.key === "ArrowRight") { pause(); next(); }
      if (e.key === "ArrowLeft") { pause(); show((i - 1 + nodes.length) % nodes.length); }
    });
    function open() {
      const s = series.find(x => x.slug === frames[i].series);
      if (!s) return;
      if (linkTarget) window.open(seriesHref(s), "_blank"); else location.href = seriesHref(s);
    }

    // Series index below the fold
    const grid = $("#series-grid");
    if (grid) {
      if (!series.length) grid.append(el("p", { class: "empty", text: "No series yet." }));
      series.forEach(s => {
        const cover = s.cover.type === "image" ? picture(s.cover, { sizes: "(max-width: 560px) 50vw, 25vw" }) : el("img", { src: s.cover.poster || "", alt: s.title, loading: "lazy" });
        grid.append(el("a", { class: "series-card", href: seriesHref(s), target: linkTarget }, [
          el("div", { class: "thumb" }, [cover]),
          el("div", { class: "meta" }, [el("span", { text: s.title }), el("span", { text: s.year || "" })]),
        ]));
      });
    }
  }

  /* Series page ----------------------------------------------------------- */
  function seriesPage() {
    const head = $("#series-head");
    if (!head || (!SINGLE && head.closest("[hidden]"))) return;
    const slug = SINGLE ? route().series : new URLSearchParams(location.search).get("s");
    if (SINGLE && !slug) { head.parentElement.hidden = true; return; }
    if (SINGLE) { head.parentElement.hidden = false; window.scrollTo(0, 0); }
    const idx = series.findIndex(s => s.slug === slug);
    const s = series[idx];
    if (!s) {
      head.append(el("h1", { text: "Series not found" }), el("p", {}, [document.createTextNode("Back to "), el("a", { href: homeHref, text: "all work" }), document.createTextNode(".")]));
      return;
    }
    document.title = `${s.title} — ${SITE.name || ""}`;
    head.append(el("h1", {}, [document.createTextNode(s.title), s.year ? el("span", { class: "year", text: s.year }) : null]),
      s.description ? el("p", { html: s.description }) : null);

    const feed = $("#feed");
    const grid = SITE.layout === "grid";
    feed.className = grid ? "grid" : "feed";
    const images = s.items.filter(it => it.type === "image");
    s.items.forEach((it, n) => {
      const fig = el("figure", { class: it.height > it.width ? "is-portrait" : "is-landscape" });
      if (it.type === "video") fig.append(video(it));
      else {
        const img = picture(it, { eager: n === 0, sizes: grid ? "(max-width: 560px) 100vw, 33vw" : "(max-width: 760px) 100vw, min(1400px, 92vw)" });
        img.addEventListener("click", () => lightbox.open(images.indexOf(it)));
        fig.append(img);
      }
      fig.append(el("figcaption", { text: it.alt || "" }));
      feed.append(fig);
    });

    const nav = $("#series-nav");
    const prev = series[(idx - 1 + series.length) % series.length], nxt = series[(idx + 1) % series.length];
    if (nav && series.length > 1) {
      nav.append(el("a", { href: seriesHref(prev) }, [el("span", { text: "Previous" }), document.createTextNode(prev.title)]),
        el("a", { href: seriesHref(nxt) }, [el("span", { text: "Next" }), document.createTextNode(nxt.title)]));
    }
    const lightbox = makeLightbox(images);
  }

  function makeLightbox(images) {
    const box = el("dialog", { class: "lightbox", "aria-label": "Image viewer" });
    const img = el("img", { alt: "" });
    const count = el("span", { class: "lb-count" });
    box.append(count, el("button", { class: "lb-close", text: "Close", "aria-label": "Close" }),
      el("button", { class: "lb-prev", "aria-label": "Previous" }), el("button", { class: "lb-next", "aria-label": "Next" }), img);
    document.body.append(box);
    let k = 0;
    function render() {
      const it = images[k];
      img.src = it.src; img.srcset = srcsetOf(it); img.sizes = "100vw"; img.alt = it.alt || "";
      count.textContent = `${k + 1} / ${images.length}`;
      const pre = images[(k + 1) % images.length]; if (pre) { const p = new Image(); p.srcset = srcsetOf(pre); p.sizes = "100vw"; p.src = pre.src; }
    }
    const api = {
      open(i) { if (!images.length) return; k = Math.max(0, i); render(); box.showModal ? box.showModal() : box.setAttribute("open", ""); document.body.classList.add("has-lightbox"); },
      close() { box.close ? box.close() : box.removeAttribute("open"); document.body.classList.remove("has-lightbox"); },
      step(d) { k = (k + d + images.length) % images.length; render(); },
    };
    $(".lb-close", box).onclick = api.close;
    $(".lb-prev", box).onclick = () => api.step(-1);
    $(".lb-next", box).onclick = () => api.step(1);
    img.onclick = () => api.step(1);
    box.addEventListener("close", () => document.body.classList.remove("has-lightbox"));
    box.addEventListener("keydown", e => {
      if (e.key === "ArrowRight") api.step(1);
      if (e.key === "ArrowLeft") api.step(-1);
    });
    // swipe on touch
    let x0 = null;
    box.addEventListener("touchstart", e => { x0 = e.touches[0].clientX; }, { passive: true });
    box.addEventListener("touchend", e => {
      if (x0 == null) return; const dx = e.changedTouches[0].clientX - x0; x0 = null;
      if (Math.abs(dx) > 40) api.step(dx < 0 ? 1 : -1);
    });
    return api;
  }

  /* Archive page ----------------------------------------------------------- */
  function archive() {
    const root = $("#archive");
    if (!root || (!SINGLE && root.hasAttribute("hidden"))) return;
    if (SINGLE && !route().archive) { root.hidden = true; return; }
    root.hidden = false;
    document.title = `Archive — ${SITE.name || ""}`;
    const items = (DATA.archive || []).slice();
    if (SITE.shuffleArchive) for (let i = items.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [items[i], items[j]] = [items[j], items[i]]; }
    const wall = $("#archive-wall");
    if (!items.length) { wall.append(el("p", { class: "empty", text: "Nothing in the archive yet. Add files to originals/_archive/ and run tools/build.py." })); return; }
    const images = items.filter(it => it.type === "image");
    const lightbox = makeLightbox(images);
    items.forEach(it => {
      const fig = el("figure");
      if (it.type === "video") fig.append(video(it));
      else {
        const img = picture(it, { sizes: "(max-width: 560px) 50vw, (max-width: 1100px) 33vw, 25vw" });
        img.addEventListener("click", () => lightbox.open(images.indexOf(it)));
        fig.append(img);
      }
      wall.append(fig);
    });
  }

  /* Info page -------------------------------------------------------------- */
  function info() {
    const root = $("#info");
    if (!root || (!SINGLE && root.hasAttribute("hidden"))) return;
    if (SINGLE && !route().info) { root.hidden = true; return; }
    root.hidden = false;
    document.title = `Information — ${SITE.name || ""}`;
    const paras = Array.isArray(SITE.bio) ? SITE.bio : [SITE.bio || ""];
    paras.filter(Boolean).forEach(t => root.append(el("p", { class: "bio", html: t })));
    const press = (SITE.press || []).filter(Boolean);
    if (press.length) root.append(el("h2", { text: "Press:" }), el("ul", {}, press.map(x =>
      typeof x === "string" ? el("li", { text: x }) : el("li", {}, [x.url ? el("a", { href: x.url, text: x.name, target: "_blank", rel: "noopener" }) : document.createTextNode(x.name)]))));
    const social = (SITE.social || []).filter(x => x && x.url);
    if (social.length) root.append(el("h2", { text: "Social Media:" }), el("ul", {}, social.map(x =>
      el("li", {}, [el("a", { href: x.url, text: x.label, target: x.url.startsWith("mailto:") ? null : "_blank", rel: "noopener" })]))));
    if (SITE.credit && SITE.credit.text) root.append(el("p", { class: "credit" }, [
      SITE.credit.url ? el("a", { href: SITE.credit.url, text: SITE.credit.text, target: "_blank", rel: "noopener" }) : document.createTextNode(SITE.credit.text)]));
  }

  const page = location.pathname.split("/").pop() || "index.html";
  header(page);
  footer();
  home();
  seriesPage();
  archive();
  info();
  if (location.hash === "#projects") { const go = () => { const t = $("#work"); if (t && !t.hidden) t.scrollIntoView(); }; requestAnimationFrame(go); window.addEventListener("load", go, { once: true }); }
  if (SINGLE) window.addEventListener("hashchange", () => { if (location.hash === "#projects") { const t = $("#work"); if (t && !t.hidden) { t.scrollIntoView({ behavior: "smooth" }); return; } } location.reload(); });
})();
